import sys

import pytest
from _pytest.reports import pytest_report_from_serializable, pytest_report_to_serializable

TESTFILE = """
def test_chained_exception_with_from():
    try:
        try:
            raise ValueError(11)
        except Exception as e1:
            raise ValueError(12) from e1
    except Exception as e2:
        raise ValueError(13) from e2


def test_chained_exception_without_from():
    try:
        try:
            raise ValueError(21)
        except Exception:
            raise ValueError(22)
    except Exception:
        raise ValueError(23)
"""


class Collector:
    def __init__(self):
        self.reports = []

    def pytest_runtest_logreport(self, report):
        self.reports.append(report)


def main():
    tmp = "repro_chain_issue_tmp"
    import os

    os.makedirs(tmp, exist_ok=True)
    with open(tmp + "/test_chained.py", "w") as f:
        f.write(TESTFILE)
    collector = Collector()
    rc = pytest.main(
        ["-p", "no:cacheprovider", tmp + "/test_chained.py"], plugins=[collector]
    )
    print("pytest rc:", rc)

    ok = True
    for rep in collector.reports:
        if rep.when != "call" or not rep.failed:
            continue
        original_text = rep.longreprtext
        data = pytest_report_to_serializable(rep)
        newrep = pytest_report_from_serializable(data)
        roundtrip_text = newrep.longreprtext
        print("=" * 70)
        print("nodeid:", rep.nodeid)
        print("original longrepr type:", type(rep.longrepr).__name__)
        print("roundtrip longrepr type:", type(newrep.longrepr).__name__)
        has_chain = hasattr(newrep.longrepr, "chain")
        print("chain preserved:", has_chain)
        print("texts equal:", original_text == roundtrip_text)
        if not has_chain or original_text != roundtrip_text:
            ok = False
            print("--- ORIGINAL ---")
            print(original_text)
            print("--- ROUNDTRIP ---")
            print(roundtrip_text)
    print("RESULT:", "BUG PRESENT" if not ok else "OK")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
"}

