def _report_to_json(report):
    """
    This was originally the serialize_report() function from xdist (ca03269).

    Returns the contents of this report as a dict of builtin entries, suitable for
    serialization.

    Experimental method.
    """

    def serialize_repr_entry(entry):
        entry_data = {"type": type(entry).__name__, "data": entry.__dict__.copy()}
        for key, value in entry_data["data"].items():
            if isinstance(value, (py.path.local, Path)):
                entry_data["data"][key] = str(value)
            elif hasattr(value, "__dict__"):
                entry_data["data"][key] = value.__dict__.copy()
        return entry_data

    def serialize_repr_traceback(reprtraceback):
        reprtraceback_data = reprtraceback.__dict__.copy()
        reprtraceback_data["reprentries"] = [
            serialize_repr_entry(entry) for entry in reprtraceback_data["reprentries"]
        ]
        return reprtraceback_data

    def serialize_repr_crash(reprcrash, exception):
        if reprcrash is not None:
            return reprcrash.__dict__.copy()
        if getattr(exception, "msg", None) is not None:
            # exception._getreprcrash() returns None if exception excargs is a string
            # (see #7856); in that case use the msg.
            return {"message": exception.msg}
        return None

    def serialize_exception_longrepr(longrepr):
        assert isinstance(longrepr, ExceptionRepr)
        result = {
            "reprcrash": serialize_repr_crash(longrepr.reprcrash, longrepr.exception),
            "reprtraceback": serialize_repr_traceback(longrepr.reprtraceback),
            "sections": longrepr.sections,
        }
        if isinstance(longrepr, ExceptionChainRepr):
            result["chain"] = []
            for repr_traceback, repr_crash, description in longrepr.chain:
                result["chain"].append(
                    {
                        "reprtraceback": serialize_repr_traceback(repr_traceback),
                        "reprcrash": serialize_repr_crash(repr_crash, ...),
                        "description": description,
                    }
                )
        else:
            result["chain"] = None
        return result
